//! The settings schema, as the core sees it: [`schema.json`](schema.json) is a
//! projection of `@loca/shared`'s `SETTINGS_SCHEMA` generated by
//! `deno task contract`, carrying only what the core reads (id, type,
//! destination, default, bounds, static options, regex rules). Secret keys are
//! the `type: "password"` fields, so a new one opts in with no manifest.

use std::collections::HashMap;
use std::sync::LazyLock;

use serde::Deserialize;
use serde_json::{Map, Value};

/// Where a setting is persisted. The core holds `core` (shared
/// `settings.json`) and `client-on-core` (the `client_settings` overlay);
/// `client-on-client` never reaches it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum Destination {
    ClientOnClient,
    ClientOnCore,
    Core,
}

impl Destination {
    /// True for the two destinations the core stores.
    pub fn is_core_stored(self) -> bool {
        !matches!(self, Destination::ClientOnClient)
    }
}

/// Which control the Client renders, and therefore what shape the value takes.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum FieldType {
    String,
    Password,
    Multiline,
    Number,
    Float,
    Boolean,
    Color,
    Shortcut,
    Select,
    Preset,
    ModelPreset,
    SttPreset,
    TtsPreset,
    NumberSlider,
    CommandPreview,
    Services,
    Storage,
    ObjectManagement,
}

impl FieldType {
    /// Render-only fields hold no persisted scalar.
    pub fn is_render_only(self) -> bool {
        matches!(
            self,
            FieldType::CommandPreview
                | FieldType::Services
                | FieldType::Storage
                | FieldType::ObjectManagement
        )
    }

    /// The free-text types whose `regex` rules are evaluated (number and float
    /// carry them too, since a numeric input's value can arrive as a string).
    pub fn is_text_like(self) -> bool {
        matches!(
            self,
            FieldType::String | FieldType::Password | FieldType::Multiline
        )
    }

    /// The wire spelling, which is what the validation messages quote.
    pub fn as_str(self) -> &'static str {
        match self {
            FieldType::String => "string",
            FieldType::Password => "password",
            FieldType::Multiline => "multiline",
            FieldType::Number => "number",
            FieldType::Float => "float",
            FieldType::Boolean => "boolean",
            FieldType::Color => "color",
            FieldType::Shortcut => "shortcut",
            FieldType::Select => "select",
            FieldType::Preset => "preset",
            FieldType::ModelPreset => "model_preset",
            FieldType::SttPreset => "stt_preset",
            FieldType::TtsPreset => "tts_preset",
            FieldType::NumberSlider => "number_slider",
            FieldType::CommandPreview => "command_preview",
            FieldType::Services => "services",
            FieldType::Storage => "storage",
            FieldType::ObjectManagement => "object_management",
        }
    }
}

/// One rule and the message shown when the value fails it.
#[derive(Debug, Clone, Deserialize)]
pub struct RegexRule {
    pub regex: String,
    #[serde(rename = "errorMessage")]
    pub error_message: String,
}

/// A field's `regex`: a bare pattern with the generic failure message, or an
/// ordered list of rules with their own.
#[derive(Debug, Clone, Deserialize)]
#[serde(untagged)]
pub enum RegexValidation {
    Pattern(String),
    Rules(Vec<RegexRule>),
}

/// One setting, projected.
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Field {
    pub id: String,
    #[serde(rename = "type")]
    pub kind: FieldType,
    pub destination: Destination,
    /// Absent for render-only fields.
    #[serde(default)]
    pub default_value: Option<Value>,
    /// Inclusive bounds, for `number`, `float` and `number_slider`.
    #[serde(default)]
    pub min: Option<f64>,
    #[serde(default)]
    pub max: Option<f64>,
    /// A static select's allowed values. Empty when the options are resolved
    /// at runtime (monitors, fonts, voices), which the core cannot check.
    #[serde(default)]
    pub options: Vec<Value>,
    #[serde(default)]
    pub regex: Option<RegexValidation>,
}

/// Every setting the schema knows, indexed.
pub struct Schema {
    fields: Vec<Field>,
    by_id: HashMap<String, usize>,
    defaults: Map<String, Value>,
    secret_keys: Vec<String>,
}

#[derive(Deserialize)]
struct Projection {
    fields: Vec<Field>,
}

impl Schema {
    fn parse(raw: &str) -> Result<Self, serde_json::Error> {
        let projection: Projection = serde_json::from_str(raw)?;
        let mut by_id = HashMap::with_capacity(projection.fields.len());
        let mut defaults = Map::new();
        let mut secret_keys = Vec::new();
        for (index, field) in projection.fields.iter().enumerate() {
            by_id.insert(field.id.clone(), index);
            if let Some(default) = field.default_value.clone() {
                defaults.insert(field.id.clone(), default);
            }
            if field.kind == FieldType::Password {
                secret_keys.push(field.id.clone());
            }
        }
        Ok(Self {
            fields: projection.fields,
            by_id,
            defaults,
            secret_keys,
        })
    }

    pub fn field(&self, id: &str) -> Option<&Field> {
        self.by_id.get(id).and_then(|i| self.fields.get(*i))
    }

    pub fn is_valid_key(&self, id: &str) -> bool {
        self.by_id.contains_key(id)
    }

    pub fn destination(&self, id: &str) -> Option<Destination> {
        self.field(id).map(|f| f.destination)
    }

    /// True when the value belongs in the vault and must never be returned
    /// over the API.
    pub fn is_secret_key(&self, id: &str) -> bool {
        self.field(id)
            .is_some_and(|f| f.kind == FieldType::Password)
    }

    /// Every persistable field's default; the sparse stores layer over this.
    pub fn defaults(&self) -> &Map<String, Value> {
        &self.defaults
    }

    pub fn secret_keys(&self) -> &[String] {
        &self.secret_keys
    }

    pub fn fields(&self) -> &[Field] {
        &self.fields
    }
}

// A panic rather than an empty fallback: an empty schema would reject every
// PATCH key and drop every default, silently.
#[allow(clippy::expect_used)]
static SCHEMA: LazyLock<Schema> = LazyLock::new(|| {
    Schema::parse(include_str!("schema.json"))
        .expect("src/settings/schema.json is corrupt; regenerate it with `deno task contract`")
});

/// The parsed schema. Parsed once, on first use.
pub fn schema() -> &'static Schema {
    &SCHEMA
}

#[cfg(test)]
#[allow(clippy::unwrap_used, clippy::expect_used)]
mod tests {
    use super::*;

    #[test]
    fn the_projection_parses() {
        let schema = schema();
        assert!(
            schema.fields().len() > 150,
            "only {} fields",
            schema.fields().len()
        );
    }

    #[test]
    fn every_field_is_indexed_once_and_carries_a_destination() {
        let schema = schema();
        let mut ids = std::collections::HashSet::new();
        for field in schema.fields() {
            assert!(ids.insert(&field.id), "{} is projected twice", field.id);
            assert_eq!(
                schema.field(&field.id).map(|f| f.destination),
                Some(field.destination),
            );
        }
        // Declared in both the stt and tts groups; the emitter collapses them.
        assert!(ids.contains(&"speech.binaryBackend".to_string()));
    }

    #[test]
    fn destinations_are_read_from_the_schema() {
        let schema = schema();
        assert_eq!(
            schema.destination("llm.contextSize"),
            Some(Destination::Core)
        );
        assert_eq!(
            schema.destination("llm.temperature"),
            Some(Destination::ClientOnCore)
        );
        assert_eq!(
            schema.destination("appearance.theme"),
            Some(Destination::ClientOnClient)
        );
        assert_eq!(schema.destination("server.bindHost"), None);
        assert!(!schema.is_valid_key("server.behindProxy"));
    }

    #[test]
    fn the_secret_keys_are_exactly_the_password_fields() {
        let mut names = schema().secret_keys().to_vec();
        names.sort();
        assert_eq!(
            names,
            [
                "dualModel.external.apiKey",
                "llm.external.apiKey",
                "stt.external.apiKey",
                "tts.external.apiKey",
            ]
        );
        assert!(schema().is_secret_key("llm.external.apiKey"));
        assert!(!schema().is_secret_key("llm.external.model"));
    }

    #[test]
    fn defaults_cover_persistable_fields_and_skip_render_only_ones() {
        let schema = schema();
        assert_eq!(
            schema.defaults().get("llm.contextSize"),
            Some(&Value::from(4096)),
        );
        assert!(schema.is_valid_key("memories.list"));
        assert!(!schema.defaults().contains_key("memories.list"));
        assert!(schema
            .field("memories.list")
            .is_some_and(|f| f.kind.is_render_only()));
    }

    #[test]
    fn bounds_options_and_regexes_survive_the_projection() {
        let schema = schema();
        let slider = schema.field("memories.maxRelevant").unwrap();
        assert_eq!((slider.min, slider.max), (Some(1.0), Some(10.0)));
        let provider = schema.field("llm.provider").unwrap();
        assert_eq!(provider.options, vec!["local", "external"]);
        let host = schema.field("llm.host").unwrap();
        assert!(matches!(host.regex, Some(RegexValidation::Rules(_))));
    }
}
